# ===================================================================
# 2. Forbidden transition invariants
# ===================================================================

class TestDocumentForbiddenTransitions:
    def test_archived_cannot_go_anywhere(self):
        """ARCHIVED is a terminal state for documents."""
        for target in DocumentState:
            if target != DocumentState.ARCHIVED:
                assert target in DOCUMENT_FORBIDDEN_TRANSITIONS[DocumentState.ARCHIVED]

    def test_failed_cannot_go_to_uploaded(self):
        assert DocumentState.UPLOADED in DOCUMENT_FORBIDDEN_TRANSITIONS[DocumentState.FAILED]

    def test_uploaded_to_processing_allowed(self):
        forbidden = DOCUMENT_FORBIDDEN_TRANSITIONS.get(DocumentState.UPLOADED, frozenset())
        assert DocumentState.PROCESSING not in forbidden


class TestExtractedFieldForbiddenTransitions:
    def test_rejected_is_terminal(self):
        for target in ExtractedFieldState:
            if target != ExtractedFieldState.REJECTED:
                assert target in EXTRACTED_FIELD_FORBIDDEN_TRANSITIONS[ExtractedFieldState.REJECTED]

    def test_validated_cannot_go_to_pending(self):
        assert ExtractedFieldState.PENDING in EXTRACTED_FIELD_FORBIDDEN_TRANSITIONS[ExtractedFieldState.VALIDATED]

    def test_pending_to_extracted_allowed(self):
        forbidden = EXTRACTED_FIELD_FORBIDDEN_TRANSITIONS.get(ExtractedFieldState.PENDING, frozenset())
        assert ExtractedFieldState.EXTRACTED not in forbidden


class TestTaskForbiddenTransitions:
    def test_cancelled_is_terminal(self):
        for target in TaskState:
            if target != TaskState.CANCELLED:
                assert target in TASK_FORBIDDEN_TRANSITIONS[TaskState.CANCELLED]

    def test_completed_cannot_go_back(self):
        assert TaskState.PENDING in TASK_FORBIDDEN_TRANSITIONS[TaskState.COMPLETED]
        assert TaskState.IN_PROGRESS in TASK_FORBIDDEN_TRANSITIONS[TaskState.COMPLETED]


class TestNotificationForbiddenTransitions:
