        assert NotificationState.PENDING in NOTIFICATION_FORBIDDEN_TRANSITIONS[NotificationState.READ]
        assert NotificationState.SENT in NOTIFICATION_FORBIDDEN_TRANSITIONS[NotificationState.READ]


class TestExportJobForbiddenTransitions:
