class TestValidateTransition:
    def test_allowed_transition_passes(self):
        # Should not raise
        validate_extracted_field_transition(
            ExtractedFieldState.PENDING, ExtractedFieldState.EXTRACTED
        )

    def test_forbidden_transition_raises(self):
        with pytest.raises(ForbiddenTransitionError) as exc_info:
            validate_extracted_field_transition(
                ExtractedFieldState.REJECTED, ExtractedFieldState.PENDING
            )
        assert exc_info.value.entity == "ExtractedField"
        assert exc_info.value.source == "rejected"
        assert exc_info.value.target == "pending"

    def test_task_allowed(self):
        validate_task_transition(TaskState.PENDING, TaskState.IN_PROGRESS)

    def test_task_forbidden(self):
        with pytest.raises(ForbiddenTransitionError):
            validate_task_transition(TaskState.CANCELLED, TaskState.PENDING)

    def test_notification_allowed(self):
        validate_notification_transition(
            NotificationState.PENDING, NotificationState.SENT
        )

    def test_notification_forbidden(self):
        with pytest.raises(ForbiddenTransitionError):
            validate_notification_transition(
                NotificationState.READ, NotificationState.PENDING
            )

    def test_export_job_allowed(self):
        validate_export_job_transition(ExportJobState.QUEUED, ExportJobState.RUNNING)

    def test_export_job_forbidden(self):
        with pytest.raises(ForbiddenTransitionError):
            validate_export_job_transition(
                ExportJobState.COMPLETED, ExportJobState.QUEUED
            )

    def test_ai_query_allowed(self):
        validate_ai_query_transition(AIQueryState.SUBMITTED, AIQueryState.PROCESSING)

    def test_ai_query_forbidden(self):
        with pytest.raises(ForbiddenTransitionError):
            validate_ai_query_transition(
                AIQueryState.COMPLETED, AIQueryState.SUBMITTED
            )


