class TestSlice1DocumentReservation:
    def test_any_document_transition_forbidden_in_slice1(self):
        """Every possible document transition must raise Slice1TransitionForbidden."""
        for source in DocumentState:
            for target in DocumentState:
                with pytest.raises(Slice1TransitionForbidden):
                    guard_document_transition_slice1(source, target)

    def test_error_message_contains_states(self):
        with pytest.raises(Slice1TransitionForbidden, match="uploaded.*processing"):
            guard_document_transition_slice1(
                DocumentState.UPLOADED, DocumentState.PROCESSING
            )


