class TestAuditImmutability:
    def test_immutable_fields_defined(self):
        assert "actor_id" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "actor_email" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "timestamp" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "created_at" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "id" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "action" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "entity_type" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "entity_id" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "old_value" in AUDIT_EVENT_IMMUTABLE_FIELDS
        assert "new_value" in AUDIT_EVENT_IMMUTABLE_FIELDS

    def test_assert_immutability_raises_for_protected_field(self):
        with pytest.raises(ValueError, match="immutable"):
            assert_audit_immutability("actor_id")

    def test_assert_immutability_raises_for_timestamp(self):
