            assert_audit_immutability("timestamp")

    def test_assert_immutability_passes_for_unknown_field(self):
        # Should not raise for a field not in the immutable set
        assert_audit_immutability("some_new_field")

    def test_audit_event_has_no_updated_at(self):
        """AuditEvent ORM model must not have an updated_at column."""
        from src.data.schema.core_lifecycle.schema import AuditEvent
        column_names = {c.name for c in AuditEvent.__table__.columns}
