@pytest.mark.usefixtures("run_migrations")
class TestAlembicMigrationSmoke:
    """
    These tests require an ephemeral PostgreSQL instance.
    They are skipped if DATABASE_URL is not set and testcontainers
    is not available.
    """

    EXPECTED_TABLES = {
        "users",
        "documents",
        "extracted_fields",
        "tasks",
        "audit_events",
        "notifications",
        "export_jobs",
        "ai_queries",
    }

    def test_all_tables_exist(self, engine):
        inspector = inspect(engine)
        tables = set(inspector.get_table_names())
        for expected in self.EXPECTED_TABLES:
            assert expected in tables, f"Table '{expected}' not found after migration"

    def test_alembic_version_table_exists(self, engine):
        inspector = inspect(engine)
        tables = set(inspector.get_table_names())
        assert "alembic_version" in tables

    def test_downgrade_and_upgrade_idempotent(self, database_url):
        """Run downgrade then upgrade again to verify reversibility."""
        from alembic.config import Config
        from alembic import command

        alembic_cfg = Config()
        alembic_cfg.set_main_option(
            "script_location",
            os.path.join(
                os.path.dirname(__file__),
                "..", "..", "..", "src", "data", "migrations",
            ),
        )
        alembic_cfg.set_main_option("sqlalchemy.url", database_url)

        # Downgrade to base
        command.downgrade(alembic_cfg, "base")

        # Verify tables are gone
        eng = sa.create_engine(database_url)
        inspector = inspect(eng)
        tables = set(inspector.get_table_names())
        for t in self.EXPECTED_TABLES:
            assert t not in tables, f"Table '{t}' still exists after downgrade"
        eng.dispose()

        # Upgrade again
        command.upgrade(alembic_cfg, "head")

        eng2 = sa.create_engine(database_url)
        inspector2 = inspect(eng2)
        tables2 = set(inspector2.get_table_names())
        for t in self.EXPECTED_TABLES:
            assert t in tables2, f"Table '{t}' missing after re-upgrade"
        eng2.dispose()


