class TestORMMetadata:
    """Verify ORM model metadata without requiring a database."""

    def test_document_state_column_exists(self):
        from src.data.schema.core_lifecycle.schema import Document
        col_names = {c.name for c in Document.__table__.columns}
        assert "state" in col_names

    def test_document_state_is_exported(self):
        """Document.state must be accessible as a class attribute (exported in schema)."""
        from src.data.schema.core_lifecycle.schema import Document
        assert hasattr(Document, "state")

    def test_all_tables_have_created_at(self):
        from src.data.schema.core_lifecycle.schema import (
            User, Document, ExtractedField, Task,
            AuditEvent, Notification, ExportJob, AIQuery,
        )
        for model in [User, Document, ExtractedField, Task,
                      AuditEvent, Notification, ExportJob, AIQuery]:
            col_names = {c.name for c in model.__table__.columns}
            assert "created_at" in col_names, f"{model.__tablename__} missing created_at"

    def test_audit_event_no_updated_at(self):
        from src.data.schema.core_lifecycle.schema import AuditEvent
        col_names = {c.name for c in AuditEvent.__table__.columns}
        assert "updated_at" not in col_names

    def test_non_audit_tables_have_updated_at(self):
        from src.data.schema.core_lifecycle.schema import (
            User, Document, ExtractedField, Task,
            Notification, ExportJob, AIQuery,
        )
        for model in [User, Document, ExtractedField, Task,
                      Notification, ExportJob, AIQuery]:
            col_names = {c.name for c in model.__table__.columns}
            assert "updated_at" in col_names, f"{model.__tablename__} missing updated_at"

    def test_all_primary_keys_are_uuid(self):
        from src.data.schema.core_lifecycle.schema import (
            User, Document, ExtractedField, Task,
            AuditEvent, Notification, ExportJob, AIQuery,
        )
        for model in [User, Document, ExtractedField, Task,
                      AuditEvent, Notification, ExportJob, AIQuery]:
            pk_cols = [c for c in model.__table__.columns if c.primary_key]
            assert len(pk_cols) == 1
            assert isinstance(pk_cols[0].type, sa.dialects.postgresql.UUID), (
                f"{model.__tablename__} PK is not UUID"
            )


