@pytest.mark.usefixtures("run_migrations")
class TestInsertSmoke:
    """Verify basic insert operations work against the real schema."""

    def test_insert_user(self, db_session):
        user_id = uuid.uuid4()
        db_session.execute(
            text(
                "INSERT INTO users (id, email, display_name) "
                "VALUES (:id, :email, :name)"
            ),
            {"id": str(user_id), "email": "test@example.com", "name": "Test User"},
        )
        row = db_session.execute(
            text("SELECT id, email FROM users WHERE id = :id"),
            {"id": str(user_id)},
        ).fetchone()
        assert row is not None
        assert row[1] == "test@example.com"

    def test_insert_document_with_state(self, db_session):
        user_id = uuid.uuid4()
        doc_id = uuid.uuid4()
        db_session.execute(
            text(
                "INSERT INTO users (id, email, display_name) "
                "VALUES (:id, :email, :name)"
            ),
            {"id": str(user_id), "email": "doc_owner@example.com", "name": "Owner"},
        )
        db_session.execute(
            text(
                "INSERT INTO documents (id, title, state, owner_id) "
                "VALUES (:id, :title, :state, :owner_id)"
            ),
            {
                "id": str(doc_id),
                "title": "Test Doc",
                "state": "uploaded",
                "owner_id": str(user_id),
            },
        )
        row = db_session.execute(
            text("SELECT state FROM documents WHERE id = :id"),
            {"id": str(doc_id)},
        ).fetchone()
        assert row is not None
        assert row[0] == "uploaded"

    def test_insert_audit_event_immutable_shape(self, db_session):
        user_id = uuid.uuid4()
        event_id = uuid.uuid4()
        entity_id = uuid.uuid4()
        db_session.execute(
            text(
                "INSERT INTO users (id, email, display_name) "
                "VALUES (:id, :email, :name)"
            ),
            {"id": str(user_id), "email": "auditor@example.com", "name": "Auditor"},
        )
        db_session.execute(
            text(
                "INSERT INTO audit_events "
                "(id, actor_id, actor_email, action, entity_type, entity_id) "
                "VALUES (:id, :actor_id, :actor_email, :action, :entity_type, :entity_id)"
            ),
            {
                "id": str(event_id),
                "actor_id": str(user_id),
                "actor_email": "auditor@example.com",
                "action": "create",
                "entity_type": "document",
                "entity_id": str(entity_id),
            },
        )
        row = db_session.execute(
            text(
                "SELECT actor_id, actor_email, timestamp, created_at "
                "FROM audit_events WHERE id = :id"
            ),
            {"id": str(event_id)},
        ).fetchone()
        assert row is not None
        assert str(row[0]) == str(user_id)
        assert row[1] == "auditor@example.com"
        # timestamp and created_at should be auto-populated
        assert row[2] is not None
        assert row[3] is not None

    def test_document_fk_constraint_enforced(self, db_session):
        """Inserting a document with a non-existent owner_id must fail."""
        doc_id = uuid.uuid4()
        fake_owner = uuid.uuid4()
        with pytest.raises(Exception):
            db_session.execute(
                text(
                    "INSERT INTO documents (id, title, state, owner_id) "
                    "VALUES (:id, :title, :state, :owner_id)"
                ),
                {
                    "id": str(doc_id),
                    "title": "Orphan",
                    "state": "uploaded",
                    "owner_id": str(fake_owner),
                },
            )
            db_session.flush()

    def test_user_email_unique_constraint(self, db_session):
        """Duplicate email must fail."""
        uid1 = uuid.uuid4()
        uid2 = uuid.uuid4()
        db_session.execute(
            text(
                "INSERT INTO users (id, email, display_name) "
                "VALUES (:id, :email, :name)"
            ),
            {"id": str(uid1), "email": "dup@example.com", "name": "First"},
        )
        with pytest.raises(Exception):
            db_session.execute(
                text(
                    "INSERT INTO users (id, email, display_name) "
                    "VALUES (:id, :email, :name)"
                ),
                {"id": str(uid2), "email": "dup@example.com", "name": "Second"},
            )
            db_session.flush()

